package app.rwun;

import android.app.Application;
import android.content.Context;
import androidx.room.Room;
import java.nio.file.*;import java.time.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;
import static org.junit.Assert.*;

/** Actual Room/SQLite and production adapters/coordinator. Fixtures are factual validation samples, not a live-device pass. */
@RunWith(RobolectricTestRunner.class) @Config(sdk=35,manifest=Config.NONE,application=Application.class)
public class RaceSyncTest {
 RaceDatabase db;RaceRepository repo;Context context;
 @Before public void setup(){context=RuntimeEnvironment.getApplication();db=Room.inMemoryDatabaseBuilder(context,RaceDatabase.class).allowMainThreadQueries().build();repo=new RaceRepository(db);}
 @After public void teardown(){db.close();}
 static RaceData.Race race(String provider,String external,String name,String date,String city,int metres){return new RaceData.Race(provider,external,date,name,city,"Western Cape","ZA","Green Point","07:00","Africa/Johannesburg","Road","","","https://example.org/"+external,"","r1",List.of(new RaceData.Distance(metres,metres/1000+" km","Road")));}
 static RaceData.Race sample(){return race("top-events","one","Coastal Run 2027","2027-07-01","Cape Town",10000);}
 RaceDatabase.Edition only(){var rows=repo.search(new RaceRepository.Filter("","","ZA","All",0,"2026-10-22","2028-01-01",false,0));assertEquals(1,rows.size());return db.catalogue().edition(rows.get(0).id);}
 @Test public void unchangedRecordsKeepContentAndOptionIdsButAdvanceSeen(){var one=sample();repo.upsert(List.of(one),100);var e=only();String option=repo.options(e.id).get(0).id;var count=repo.upsert(List.of(one),200);assertEquals(1,count.unchanged());assertEquals(e.contentVersion,only().contentVersion);assertEquals(option,repo.options(e.id).get(0).id);assertEquals(200,db.catalogue().lastSeen(e.id));}
 @Test public void changedFieldsUpdateInPlaceAndKeepUserGoal(){repo.upsert(List.of(sample()),100);var e=only();String option=repo.options(e.id).get(0).id;repo.save(e.id,option);var saved=db.catalogue().saved(e.id);saved.reminderMinutes=60;saved.goalPlanId="my-existing-plan";db.catalogue().save(saved);
  var changed=race("top-events","one","Coastal Run renamed 2027","2027-07-02","Cape Town",10000);repo.upsert(List.of(changed),200);assertEquals(e.id,only().id);assertEquals("2027-07-02",only().date);assertEquals(option,repo.options(e.id).get(0).id);var after=db.catalogue().saved(e.id);assertEquals(option,after.distanceId);assertEquals(Integer.valueOf(60),after.reminderMinutes);assertEquals("my-existing-plan",after.goalPlanId);}
 @Test public void exactCrossProviderEvidenceMergesButDistancesStayDistinct(){repo.upsert(List.of(sample()),100);repo.upsert(List.of(race("bield","two","Coastal Run 2027","2027-07-01","Cape Town",21098)),200);var e=only();assertEquals(2,repo.references(e.id).size());assertEquals(2,repo.options(e.id).size());assertNotEquals(repo.options(e.id).get(0).id,repo.options(e.id).get(1).id);}
 @Test public void uncertainNamesOrEditionsStaySeparate(){repo.upsert(List.of(sample(),race("bield","other","Coastal Run Charity Team","2027-07-01","Cape Town",10000),race("top-events","one","Coastal Run 2028","2028-07-01","Cape Town",10000)),100);assertEquals(3,repo.search(new RaceRepository.Filter("","","ZA","All",0,"2026-01-01","2029-01-01",false,0)).size());}
 @Test public void missingSupportingLocationNeverFuzzyMerges(){var a=new RaceData.Race("a","1","2027-07-01","Same Race","","","ZA","","","","Unknown","","","https://a.example/race","","",List.of());var b=new RaceData.Race("b","2","2027-07-01","Same Race","","","ZA","","","","Unknown","","","https://b.example/race","","",List.of());repo.upsert(List.of(a,b),1);assertEquals(2,repo.search(new RaceRepository.Filter("","","ZA","All",0,"2027-01-01","2028-01-01",false,0)).size());}
 @Test public void removedDistanceRetainedUnavailableAndSelectionSurvives(){repo.upsert(List.of(sample()),100);var e=only();String old=repo.options(e.id).get(0).id;repo.save(e.id,old);repo.upsert(List.of(race("top-events","one","Coastal Run 2027","2027-07-01","Cape Town",5000)),200);assertEquals(old,db.catalogue().saved(e.id).distanceId);assertFalse(db.catalogue().option(old).available);assertEquals(2,repo.options(e.id).size());}
 @Test public void absenceAndProviderFailureNeverDelete(){repo.upsert(List.of(sample()),100);repo.upsert(List.of(),200);assertNotNull(only());assertEquals(100,db.catalogue().lastSeen(only().id));}
 @Test public void diskReopenRetainsIdsAndSavedDistanceOffline(){String name="race-test-"+UUID.randomUUID()+".db";RaceDatabase disk=Room.databaseBuilder(context,RaceDatabase.class,name).allowMainThreadQueries().build();RaceRepository first=new RaceRepository(disk);first.upsert(List.of(sample()),100);String id=first.search(new RaceRepository.Filter("","","ZA","All",0,"2027-01-01","2028-01-01",false,0)).get(0).id;String distance=first.options(id).get(0).id;first.save(id,distance);disk.close();RaceDatabase reopened=Room.databaseBuilder(context,RaceDatabase.class,name).allowMainThreadQueries().build();try{assertEquals(distance,reopened.catalogue().saved(id).distanceId);assertEquals("Coastal Run 2027",reopened.catalogue().edition(id).name);}finally{reopened.close();context.deleteDatabase(name);}}
 @Test public void countryAndSurfaceFiltersAndLiteralWildcards(){repo.upsert(List.of(sample()),1);assertEquals(0,repo.search(new RaceRepository.Filter("%","","ZA","All",0,"2027-01-01","2028-01-01",false,0)).size());assertEquals(0,repo.search(new RaceRepository.Filter("","","GB","All",0,"2027-01-01","2028-01-01",false,0)).size());assertEquals(0,repo.search(new RaceRepository.Filter("","","ZA","Trail",0,"2027-01-01","2028-01-01",false,0)).size());assertEquals(1,repo.search(new RaceRepository.Filter("coastal","Western Cape","ZA","Road",10000,"2027-01-01","2028-01-01",false,0)).size());}
 @Test public void realTopEventsShapeDecodesEntitiesAndUnknownFees()throws Exception{var page=new TopEventsRaceProvider().parse(fixture("top-events.json"),LocalDate.of(2026,10,22));assertFalse(page.races().isEmpty());var first=page.races().get(0);assertTrue(first.name().contains("&"));assertEquals("",first.fee());assertEquals("Trail",first.surface());assertEquals(Set.of(5000,10000),new HashSet<>(first.distances().stream().map(RaceData.Distance::metres).toList()));assertEquals("",first.city());assertEquals("",first.description());}
 @Test public void realRunSignupShapeExcludesFundraiserOnly()throws Exception{var page=new RunSignupRaceProvider().parse(fixture("runsignup.json"),LocalDate.of(2026,10,22));assertEquals(1,page.races().size());assertEquals(1,page.races().get(0).distances().size());assertEquals(42165,page.races().get(0).distances().get(0).metres());assertFalse(new RunSignupRaceProvider().blockedReason().isEmpty());}
 @Test public void bieldSkipsHistoricalRowsAndDoesNotInventTimezone()throws Exception{String json="{\"meta\":{\"page\":1,\"pages\":2},\"races\":[{\"id\":\"old\",\"name\":\"Old\",\"date\":\"2020-01-01\"},{\"id\":\"future\",\"name\":\"Future\",\"date\":\"2027-01-01\",\"country\":\"GB\",\"location\":\"Hills\",\"distance_km\":50,\"terrain\":\"trail\",\"url\":\"https://example.org/future\"}]}";var page=new BieldRaceProvider().parse(json,LocalDate.of(2026,10,22));assertEquals(1,page.races().size());assertEquals("",page.races().get(0).timezone());assertTrue(page.more());}
 @Test public void distanceParsingRejectsRangesAndNeverInfersFees(){assertEquals(2,RaceData.distances("10km & 5km", "Road").size());assertEquals(0,RaceData.distances("5-10km", "Road").size());assertEquals(0,RaceData.distances("Entry R150, 2027 edition", "Road").size());assertEquals("",sample().fee());assertEquals("Run & walk",RaceData.text("<script>evil()</script><b>Run &amp; walk</b>",100));}
 @Test public void metadataRevisionDoesNotRewriteRaceContent(){repo.upsert(List.of(sample()),1);var e=only();var s=sample();var revised=new RaceData.Race(s.provider(),s.externalId(),s.date(),s.name(),s.city(),s.province(),s.country(),s.venue(),s.time(),s.timezone(),s.surface(),s.fee(),s.description(),s.url(),s.entryUrl(),"new-revision",s.distances());assertEquals(1,repo.upsert(List.of(revised),2).unchanged());assertEquals(e.contentVersion,only().contentVersion);}
 @Test public void planningSnapshotAndHistoryAreUntouchedByRefresh()throws Exception{RunStore store=new RunStore(context);store.save(new PlanEngine.Config(8,3,12,10,LocalDate.now()));String before=store.backupPreferences().toString();repo.upsert(List.of(sample()),1);var e=only();repo.save(e.id,repo.options(e.id).get(0).id);repo.upsert(List.of(race("top-events","one","Renamed","2027-07-08","Cape Town",5000)),2);assertEquals(before,store.backupPreferences().toString());}
 static String fixture(String file)throws Exception{return new String(Files.readAllBytes(Path.of(System.getProperty("rwun.root"),"tests/fixtures/races",file)),java.nio.charset.StandardCharsets.UTF_8);}
 static class Provider implements RaceProvider {final String name;final int pages;Provider(String n,int p){name=n;pages=p;}public String id(){return name;}public String endpoint(int page,String since){return "https://example.org/"+name+"/"+page;}public Page parse(String json,LocalDate today){int page=Integer.parseInt(json);return new Page(List.of(race(name,"ref"+page,name+" race "+page,"2027-07-01","Cape Town",10000)),page<pages,pages,0);}}
 @Test public void paginationAndConditional304KeepCachedRaces()throws Exception{AtomicInteger requests=new AtomicInteger();RaceHttp first=new RaceHttp(){public Response get(String url,RaceDatabase.HttpPage previous){requests.incrementAndGet();return new Response(200,url.substring(url.lastIndexOf('/')+1),"etag","");}};var result=new RaceSyncCoordinator(repo,first,List.of(new Provider("pages",3))).sync();assertEquals(1,result.succeeded());assertEquals(3,requests.get());assertEquals(3,repo.search(new RaceRepository.Filter("","","ZA","All",0,"2027-01-01","2028-01-01",false,0)).size());RaceHttp cached=new RaceHttp(){public Response get(String u,RaceDatabase.HttpPage p){assertNotNull(p);assertEquals("etag",p.etag);return new Response(304,"","etag","");}};assertEquals(1,new RaceSyncCoordinator(repo,cached,List.of(new Provider("pages",3))).sync().succeeded());}
 @Test public void oneProviderFailureDoesNotBlockOtherProviders()throws Exception{RaceHttp h=new RaceHttp(){public Response get(String url,RaceDatabase.HttpPage p)throws Exception{if(url.contains("bad"))throw new java.io.IOException("offline");return new Response(200,"1","","");}};var result=new RaceSyncCoordinator(repo,h,List.of(new Provider("bad",1),new Provider("good",1))).sync();assertEquals(1,result.failed());assertEquals(1,result.succeeded());assertTrue(result.retry());assertEquals("good race 1",only().name);}
 @Test public void concurrentSyncIsSingleFlight()throws Exception{CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1);RaceHttp h=new RaceHttp(){public Response get(String url,RaceDatabase.HttpPage p)throws Exception{entered.countDown();if(!release.await(5,TimeUnit.SECONDS))throw new java.io.IOException("test deadline");return new Response(200,"1","","");}};var coordinator=new RaceSyncCoordinator(repo,h,List.of(new Provider("a",1)));CompletableFuture<RaceSyncCoordinator.Result> running=CompletableFuture.supplyAsync(()->{try{return coordinator.sync();}catch(Exception e){throw new RuntimeException(e);}});assertTrue(entered.await(5,TimeUnit.SECONDS));assertTrue(new RaceSyncCoordinator(repo,new RaceHttp(),List.of()).sync().alreadyRunning());release.countDown();assertEquals(1,running.get(5,TimeUnit.SECONDS).succeeded());}
 @Test public void databaseLeasePreventsAnotherCoordinatorAfterProcessFlagReset(){assertTrue(repo.acquire("first",1000));assertFalse(repo.acquire("second",1001));repo.release("second");assertFalse(repo.acquire("second",1002));repo.release("first");assertTrue(repo.acquire("second",1003));}
 @Test public void failedPaginationDoesNotAdvanceIncrementalCursor()throws Exception{RaceHttp h=new RaceHttp(){public Response get(String url,RaceDatabase.HttpPage p)throws Exception{if(url.endsWith("/2"))throw new java.io.IOException("second page failed");return new Response(200,"1","","");}};assertTrue(new RaceSyncCoordinator(repo,h,List.of(new Provider("partial",3))).sync().retry());var status=db.catalogue().sync("partial");assertEquals(0,status.success);assertEquals("",status.incrementalSince);assertNotNull(only());}
 @Test public void unchangedRaceDoesNotExecuteContentWrites(){repo.upsert(List.of(sample()),1);var sql=db.getOpenHelper().getWritableDatabase();sql.execSQL("CREATE TABLE write_audit(n INTEGER)");sql.execSQL("INSERT INTO write_audit VALUES(0)");sql.execSQL("CREATE TRIGGER edition_audit AFTER UPDATE ON race_editions BEGIN UPDATE write_audit SET n=n+1; END");sql.execSQL("CREATE TRIGGER option_audit AFTER UPDATE ON race_distances BEGIN UPDATE write_audit SET n=n+1; END");sql.execSQL("CREATE TRIGGER ref_audit AFTER INSERT ON race_refs BEGIN UPDATE write_audit SET n=n+1; END");repo.upsert(List.of(sample()),2);try(var cursor=sql.query("SELECT n FROM write_audit")){assertTrue(cursor.moveToFirst());assertEquals(0,cursor.getInt(0));}}
 @Test @Config(application=RwunApplication.class) public void foregroundNavigationAndRotationDoNotRescheduleCompletedWork(){RwunApplication app=(RwunApplication)RuntimeEnvironment.getApplication();var jobs=app.getSystemService(android.app.job.JobScheduler.class);jobs.cancel(RaceSyncJob.ID);android.app.Activity a=new android.app.Activity();app.onActivityStarted(a);assertNotNull(jobs.getPendingJob(RaceSyncJob.ID));jobs.cancel(RaceSyncJob.ID);app.onActivityStarted(new android.app.Activity());app.onActivityStopped(a);assertNull(jobs.getPendingJob(RaceSyncJob.ID));app.onActivityStopped(a);org.robolectric.Shadows.shadowOf(android.os.Looper.getMainLooper()).idleFor(java.time.Duration.ofMillis(1100));app.onActivityStarted(a);assertNotNull(jobs.getPendingJob(RaceSyncJob.ID));jobs.cancel(RaceSyncJob.ID);}
 @Test public void pageSpecific304DoesNotRefreshAbsentReferences(){repo.upsert(List.of(sample()),100,"https://example.org/page1");var other=race("top-events","other","Other Race","2027-07-02","Cape Town",5000);repo.upsert(List.of(other),100,"https://example.org/page2");db.catalogue().confirmPage("top-events","https://example.org/page1",200);String one=db.catalogue().reference("top-events","one","2027").editionId;String two=db.catalogue().reference("top-events","other","2027").editionId;assertEquals(200,db.catalogue().lastSeen(one));assertEquals(100,db.catalogue().lastSeen(two));}
 @Test public void pageLimitRetainsPartialCatalogueAndReportsTruncation()throws Exception{RaceHttp h=new RaceHttp(){public Response get(String url,RaceDatabase.HttpPage p){return new Response(200,url.substring(url.lastIndexOf('/')+1),"","");}};assertTrue(new RaceSyncCoordinator(repo,h,List.of(new Provider("limited",21))).sync().retry());assertTrue(db.catalogue().sync("limited").truncated);assertEquals(20,db.catalogue().sync("limited").pages);}
 @Test public void repeatedPageCannotCauseAnInfiniteFetch()throws Exception{AtomicInteger calls=new AtomicInteger();RaceHttp h=new RaceHttp(){public Response get(String url,RaceDatabase.HttpPage p){calls.incrementAndGet();return new Response(200,"1","","");}};assertTrue(new RaceSyncCoordinator(repo,h,List.of(new Provider("repeat",3))).sync().retry());assertEquals(2,calls.get());}
 @Test public void selectedRaceTrainingSnapshotSurvivesProviderReschedule()throws Exception{repo.upsert(List.of(sample()),1);String id=only().id;String distance=repo.options(id).get(0).id;JSONObject selected=repo.planningRace(id,distance);repo.save(id,distance);RunStore store=new RunStore(context);var draft=RaceTraining.draft(LocalDate.now(),LocalDate.parse(selected.getString("date")),10,14,Set.of(DayOfWeek.TUESDAY,DayOfWeek.THURSDAY,DayOfWeek.SUNDAY),DayOfWeek.SUNDAY,12,PaceProfile.unset(),List.of(),false);JSONObject options=new JSONObject().put("mode",draft.preferences().mode()).put("weekdays",new JSONArray(List.of(2,4,7))).put("longDay",7);store.createRacePlan(store.proposalFingerprint(),draft.config(),PaceProfile.unset(),selected,options,draft.sessions());String snapshot=store.v103().getJSONObject("race").toString();repo.upsert(List.of(race("top-events","one","Coastal Run 2027","2027-07-02","Cape Town",5000)),2);assertEquals(snapshot,store.v103().getJSONObject("race").toString());assertEquals(distance,db.catalogue().saved(id).distanceId);}

 @Test public void malformedLegacyCacheCannotBlockOtherSources()throws Exception{java.io.File old=new java.io.File(context.getFilesDir(),"race-catalogue.json");Files.write(old.toPath(),"invalid legacy JSON".getBytes(java.nio.charset.StandardCharsets.UTF_8));try{repo.seed(context);assertNotNull(db.catalogue().sync("_seed"));assertFalse(db.catalogue().sync("_seed").error.isEmpty());assertEquals("invalid legacy JSON",new String(Files.readAllBytes(old.toPath()),java.nio.charset.StandardCharsets.UTF_8));repo.upsert(List.of(sample()),1);assertNotNull(db.catalogue().reference("top-events","one","2027"));}finally{old.delete();}}
 @Test public void internationalRacesNeedExplicitCountrySelection(){var gb=new RaceData.Race("bield","gb","2027-07-01","British race","London","","GB","Park","","","Road","","","https://example.org/gb","","",List.of(new RaceData.Distance(21098,"Half marathon","Road")));repo.upsert(List.of(gb,sample()),1);assertEquals(1,repo.search(new RaceRepository.Filter("","","ZA","All",0,"2027-01-01","2028-01-01",false,0)).size());assertEquals(2,repo.search(new RaceRepository.Filter("","","","All",0,"2027-01-01","2028-01-01",false,0)).size());}
 @Test public void providersNeverExceedTwoConcurrentRequests()throws Exception{AtomicInteger active=new AtomicInteger(),maximum=new AtomicInteger();RaceHttp h=new RaceHttp(){public Response get(String url,RaceDatabase.HttpPage p)throws Exception{int n=active.incrementAndGet();maximum.accumulateAndGet(n,Math::max);try{Thread.sleep(50);return new Response(200,"1","","");}finally{active.decrementAndGet();}}};var result=new RaceSyncCoordinator(repo,h,List.of(new Provider("a",1),new Provider("b",1),new Provider("c",1),new Provider("d",1))).sync();assertEquals(4,result.succeeded());assertEquals(2,maximum.get());}

 @Test public void sameCityAndDistanceWithConflictingVenuesRemainSeparate(){var a=sample();var b=new RaceData.Race("bield","different",a.date(),a.name(),a.city(),a.province(),a.country(),"Different stadium",a.time(),a.timezone(),a.surface(),a.fee(),a.description(),"https://other.example/event","","",a.distances());repo.upsert(List.of(a,b),1);assertEquals(2,repo.search(new RaceRepository.Filter("","","ZA","All",0,"2027-01-01","2028-01-01",false,0)).size());}

 @Test public void verifiedBieldRedirectAllowedButArbitraryRedirectsFail()throws Exception{var from=java.net.URI.create("https://app.bield.run/api/races/public.json?page=1");assertEquals("zlphtleymloulgqkvkev.supabase.co",RaceHttp.redirect(from,"https://zlphtleymloulgqkvkev.supabase.co/functions/v1/races-public-feed?page=1").getHost());try{RaceHttp.redirect(from,"https://unverified.example/data");fail("Unverified host must not be followed");}catch(java.io.IOException expected){}try{RaceHttp.redirect(from,"http://app.bield.run/feed");fail("No HTTP downgrade");}catch(java.io.IOException expected){}}

 @Test public void multiDayEventsCannotGuessTheDistanceRaceDay()throws Exception{var page=new TopEventsRaceProvider().parse(fixture("top-events.json"),LocalDate.of(2026,10,22));var multi=page.races().stream().filter(r->!r.date().equals(r.endDate())).findFirst().orElseThrow();repo.upsert(List.of(multi),1);var card=repo.search(new RaceRepository.Filter("","","ZA","All",0,"2026-01-01","2028-01-01",false,0)).get(0);assertNotEquals(card.date,card.endDate);try{repo.planningRace(card.id,repo.options(card.id).get(0).id);fail("Unknown individual race day must require manual confirmation");}catch(IllegalArgumentException expected){assertTrue(expected.getMessage().contains("multi-day"));}}

}
